	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Collect all files to include in the commit
	allFiles := make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
